import{_ as s,o as n,c as r,ah as a}from"./chunks/framework.DDXs_i7t.js";const u=JSON.parse('{"title":"Tages-Recap: Der Wöginger-Prozess am Landesgericht Linz","description":"Eine Zusammenfassung des ersten großen Prozesstages am 3. März 2026. Intervention oder Rechtsbruch?","frontmatter":{"title":"Tages-Recap: Der Wöginger-Prozess am Landesgericht Linz","description":"Eine Zusammenfassung des ersten großen Prozesstages am 3. März 2026. Intervention oder Rechtsbruch?","date":"2026-03-03T00:00:00.000Z"},"headers":[],"relativePath":"logbuch/2026-03-03-zusammenfassung-woeginger-prozess.md","filePath":"logbuch/2026-03-03-zusammenfassung-woeginger-prozess.md"}'),t={name:"logbuch/2026-03-03-zusammenfassung-woeginger-prozess.md"};function i(o,e,g,d,h,l){return n(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="⚖️-tages-recap-der-woginger-prozess-am-03-marz-2026" tabindex="-1">⚖️ Tages-Recap: Der Wöginger-Prozess am 03. März 2026 <a class="header-anchor" href="#⚖️-tages-recap-der-woginger-prozess-am-03-marz-2026" aria-label="Permalink to &quot;⚖️ Tages-Recap: Der Wöginger-Prozess am 03. März 2026&quot;">​</a></h1><p>Heute am Landesgericht Linz wurde Geschichte geschrieben – oder zumindest ein Kapitel über die politische Kultur Österreichs neu verfasst. Hier ist die Zusammenfassung des ersten großen Prozesstages:</p><h3 id="_1-regionalpolitik-oder-postenschacher" tabindex="-1"><strong>1. Regionalpolitik oder Postenschacher?</strong> <a class="header-anchor" href="#_1-regionalpolitik-oder-postenschacher" aria-label="Permalink to &quot;**1. Regionalpolitik oder Postenschacher?**&quot;">​</a></h3><p>August Wöginger und sein Verteidigerteam versuchten, die Intervention beim damaligen Kabinettschef Thomas Schmid als „klassisches Bürgeranliegen“ und „notwendige Regionalpolitik“ zu rahmen. Das Argument: Ein Klubobmann müsse sich für fähige Köpfe in seiner Heimatregion einsetzen dürfen.</p><h3 id="_2-die-nackten-zahlen-der-wksta" tabindex="-1"><strong>2. Die nackten Zahlen der WKStA</strong> <a class="header-anchor" href="#_2-die-nackten-zahlen-der-wksta" aria-label="Permalink to &quot;**2. Die nackten Zahlen der WKStA**&quot;">​</a></h3><p>Die Staatsanwaltschaft hielt mit den Fakten des Besetzungsverfahrens dagegen. Im Mittelpunkt stand die fachliche Überlegenheit der Beamtin <strong>Christa Scharf</strong>:</p><ul><li><strong>Christa Scharf:</strong> 98 Punkte im Hearing (Bestreihung).</li><li><strong>ÖVP-Bürgermeister:</strong> 62 Punkte. Bekam dennoch den Posten.</li></ul><p>Die WKStA wertet Wögingers SMS an Schmid („Chef, bitte anschaun“) als klaren Impuls zum Amtsmissbrauch.</p><h3 id="_3-ausblick-der-showdown-am-donnerstag" tabindex="-1"><strong>3. Ausblick: Der Showdown am Donnerstag</strong> <a class="header-anchor" href="#_3-ausblick-der-showdown-am-donnerstag" aria-label="Permalink to &quot;**3. Ausblick: Der Showdown am Donnerstag**&quot;">​</a></h3><p>Die Spannung steigt: Am <strong>5. März</strong> wird Christa Scharf selbst im Zeugenstand erwartet. Ihr Auftritt gilt als das moralische Herzstück des Prozesses. Wir dokumentieren diesen Moment als zentrales Motiv für den Abschluss unserer Mockumentary.</p><blockquote><p><em>&quot;Jeder Gefallen ist ein Punkt in einem größeren Mosaik. Wir nennen es den Pointillismus des Geldes.&quot;</em> — Auszug aus dem Drehbuch, Teil 4.</p></blockquote><hr><p><em>Berichterstattung vom 03. März 2026. Bleiben Sie dran für weitere Updates aus dem Gerichtssaal.</em></p>',13)])])}const m=s(t,[["render",i]]);export{u as __pageData,m as default};
